(()=>{'use strict';const URL='https://ahslifnthiwfkmaswjno.supabase.co',KEY='sb_publishable_M4UtzEbCLwMCd9LanFWw5g_5b7-fWda',sb=window.supabase?.createClient?.(URL,KEY,{auth:{persistSession:true,autoRefreshToken:true}}),$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],filter='all';async function session(){const r=await sb.auth.getSession();if(!r.data.session){location.href='/staff';return null}const u=await sb.from('staff').select('id,is_active').eq('id',r.data.session.user.id).maybeSingle();if(u.error||!u.data?.is_active){$('opsMessage').textContent='Staff access required.';return null}return r.data.session}function render(){const list=filter==='all'?rows:rows.filter(x=>x.status===filter);$('orders').innerHTML=list.length?list.map(o=>`<article class="order"><div class="order-main"><strong>${esc(o.order_number)}</strong><span class="status-pill">${esc(o.status)}</span><p>${esc(o.customer_name)} · ${esc(o.customer_phone)}<br>${esc(o.delivery_address)}</p><div class="order-items">${(o.shop_order_items||[]).map(i=>`<span class="order-item">${esc(i.product_name)} × ${i.quantity}</span>`).join('')}</div></div><div class="order-actions"><b>$${Number(o.total_usd||0).toFixed(2)}</b><small>${new Date(o.created_at).toLocaleString()}</small><br><select data-order-status="${o.id}" aria-label="Update order status">${['pending','confirmed','packed','in_transit','delivered','cancelled'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></div></article>`).join(''):'<p>No orders in this view.</p>'}async function load(){const s=await session();if(!s)return;const [orders,products]=await Promise.all([sb.from('shop_orders').select('id,order_number,status,total_usd,customer_name,customer_phone,delivery_address,created_at,shop_order_items(product_name,quantity)').order('created_at',{ascending:false}).limit(100),sb.from('shop_products').select('inventory_count,reserved_count,is_active').limit(100)]);if(orders.error){$('opsMessage').textContent=orders.error.message;return}rows=orders.data||[];$('openCount').textContent=rows.filter(x=>!['delivered','cancelled'].includes(x.status)).length;$('reservedCount').textContent=(products.data||[]).reduce((n,x)=>n+Number(x.reserved_count||0),0);$('productCount').textContent=(products.data||[]).filter(x=>x.is_active).length;render()}document.addEventListener('change',async e=>{const select=e.target.closest('[data-order-status]');if(!select)return;select.disabled=true;$('opsMessage').textContent='Updating…';const {error}=await sb.rpc('shop_update_order_status',{p_order_id:select.dataset.orderStatus,p_status:select.value});if(error){$('opsMessage').textContent=error.message;await load();return}$('opsMessage').textContent='Order updated.';await load()});$('statusFilter').onchange=e=>{filter=e.target.value;render()};$('refresh').onclick=load;window.addEventListener('DOMContentLoaded',load)})();
